-- Daily challenges for 2026-10-21: two new themes, 365 to-dos each.
-- Generated by tools/challenges_sql.py --since 2026-10-21. The routine loads the same rows in
-- re-runnable pieces from tools/challenges_sync.py; the GitHub workflow applies this file once
-- the SUPABASE_DB_URL secret is set.

-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('planning-small-adventures', 'Planning Small Adventures', 'For anyone whose weeks have started to look the same. Each day is one small step toward a little adventure close to home, from a new street to walk to a day trip you finally plan, so ordinary life gets a spark of something new.', 'Play', 365, array['Self-Care', 'Motivation']::text[], 1, '2026-10-21T17:00:00+00:00'::timestamptz),
  ('getting-through-a-hard-day', 'Getting Through a Hard Day', 'For anyone facing a day that feels heavy, long or simply too much. Each day is one small, steadying thing to do in the middle of it, from a glass of water to one honest text, so a hard day gets a little more bearable.', 'Stress', 365, array['Resilience', 'Self-Compassion', 'Stress']::text[], 1, '2026-10-21T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('planning-small-adventures', 'getting-through-a-hard-day');

